import Foundation
@testable import DogecoinKit

/// Real Dogecoin mainnet data, fetched from the P2P network.
///
/// `ancestors` are the best-chain headers at heights 6,341,580–6,341,590 with
/// their cumulative chain work; `mergeMinedEntries` are the next three
/// headers (6,341,591–6,341,593) exactly as a `headers` message carries them,
/// AuxPoW proof included.
enum RealChainFixtures {
    struct Ancestor {
        let height: Int32
        let headerHex: String
        let chainWorkHex: String
    }

    static let ancestors: [Ancestor] = [
        Ancestor(height: 6341580, headerHex: "04016200872a94f5e3fcfaacfb2caf7046515195c65ba93b9c11cf764b6c9e9eed1393f77956367a33d238c14eb98c8657b1224e6b3a54aa419cc853584703cf24835a5c2ea0886a53305d1900000000", chainWorkHex: "8f1adf00c49da833453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341581, headerHex: "04016200d7c81c2f7596b51d7b8f3c4bd37da2372a1fdd7635790fad40e10bb04bc2c3ac312f37648afe77634007cca38108461b825cf5be47414acc5035e581a0739f9b34a0886a1651521900000000", chainWorkHex: "9be0edf3b0c2c436453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341582, headerHex: "04016200a9711c5740537c39117573199814797e5fdf46c26c2370c56e525f1ac126bb6b5fd41b01be0364b55307a9daaba75a41658a8e9350a03b9e19da50a823674e709fa0886ac7154a1900000000", chainWorkHex: "37a053577f5d393a453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341583, headerHex: "04016200696e495ddecb2d89a67644ea17815336ff6aba4d9813715b2abe0696a015f8cedbefc2308398a75d6c455554942055cf990ae8f1208e1463151a0ff46e2a52cfa4a0886a4242501900000000", chainWorkHex: "397410c867ec693d453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341584, headerHex: "04016200375d46fc715babbe65952ffae02b584798ad8bb009ba54b5ecb955da6b52a1606a566b63ae920da56366d49829ff45a1a9fd3f5220ef1081b22d5724dcfd7014c2a0886aa13b481900000000", chainWorkHex: "fdb1f4dfe535f540453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341585, headerHex: "04016200a980bf898004da112dad401452e080cd2172efaa71406feafce2a271f03e0fba864dc8c5db405a8d78831a98d3c994afd1dda753b9dc98ebc14437869da30adf21a2886a0c9f441900000000", chainWorkHex: "4d4197f4e53fb044453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341586, headerHex: "04016200dc584d7f067bbafa594c34422645b34a3a4836a77c466087e4a84e3c8fd0fee714e4c62b3745dd979f37b0530e20f37ab6f36b6342cdbd7526dabcd08debab6e23a2886a92ee661900000000", chainWorkHex: "824bae573bf12c47453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341587, headerHex: "04016200847cb3cff5ebb031fd70517e346d6a6ce36d0a09f6d73d3899c9c2692b83bccb3553f396e57c9948083522be3ef870f929a30e21058087c129a0df5c5a4a1b3425a2886a56ec5a1900000000", chainWorkHex: "02e935fdfeb9fd49453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341588, headerHex: "04016200c4a780c1800dfe9fdf280aed59d7bbcafd52178f398b8c2fed3fedb406a870c85e79238062893efd8e30918187d637708276f878e3cd452fd29f4e9fe825a90930a2886ac350501900000000", chainWorkHex: "4accb5c871b52d4d453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341589, headerHex: "0401620049268e8c4763b1c201a4aaa5db23ed384b6683221ccc22dc3c878254254064e21f4022f2a736dae4e8b3a6612a1b7fcd0502e4863bc440c75367ce0b6dfb7afaafa2886aaf48481900000000", chainWorkHex: "0340c00c145bb850453300000000000000000000000000000000000000000000"),
        Ancestor(height: 6341590, headerHex: "0401620019d628e95ab173ff7751c5166a0991630e1a5cbe76b9ba5068525fa5ac2e1faa45a65927b5e6d619896fd827f679961535c41d7d473fd17dfd85c1ed5daa05b605a3886af9eb511900000000", chainWorkHex: "87fa006fa856d853453300000000000000000000000000000000000000000000"),
    ]

    static let mergeMinedEntries: [String] = [
        "",
        "",
        "",
    ]

    /// The three merge-mined entries as the payload of a `headers` message.
    static func headersPayload() -> Data {
        var payload = VarInt(UInt64(mergeMinedEntries.count)).serialize()
        for entry in mergeMinedEntries {
            payload.append(Data(hexString: entry) ?? Data())
            payload.append(0)
        }
        return payload
    }

    /// The three merge-mined entries parsed as a `headers` message would be.
    static func parsedEntries() -> [HeadersMessage.Entry] {
        HeadersMessage.parse(from: headersPayload())?.entries ?? []
    }

    /// A mainnet header chain whose database holds exactly the ancestors.
    static func headerChainAtTip() async throws -> HeaderChain {
        let directory = TestDirectories.unique()
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        let database = try HeaderDatabase(path: directory.appendingPathComponent("headers.sqlite").path)
        try database.insertHeaders(storedAncestors().map { HeaderRecord(storedHeader: $0, isInBestChain: true) })

        let chain = HeaderChain(network: .mainnet, storageDirectory: directory)
        try await chain.setup()
        return chain
    }

    static func storedAncestors() -> [StoredHeader] {
        ancestors.compactMap { ancestor in
            guard let bytes = Data(hexString: ancestor.headerHex),
                  let header = BlockHeader.parse(from: bytes),
                  let work = Data(hexString: ancestor.chainWorkHex) else { return nil }
            return StoredHeader(header: header, height: ancestor.height, chainWork: work)
        }
    }
}

/// Two competing branches on top of the testnet genesis block, mined for
/// these tests at the minimum difficulty, so they pass real proof-of-work
/// validation:
///
///     genesis ── a1
///        └────── b1 ── b2
///
/// `a1` and `b1` each hold `transaction` as their only transaction; `b2`
/// holds something else. The `b` branch has more work once `b2` arrives.
enum ReorgFixtures {
    /// Pays 1 DOGE to the public key hash `42…42`.
    static let transaction = hex("010000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff0100e1f505000000001976a914424242424242424242424242424242424242424288ac00000000")

    /// The public key hash `transaction` pays to
    static let paidPubkeyHash = Data(repeating: 0x42, count: 20)

    static let a1 = header("010000009e555073d0c4f36456db8951f449704d544d2826d9aa60636b40374626780abb8568d2dcae16aefa97bca36d32011c512890edbaaafb26ef46fe981fdc7a32b61da8f052f0ff0f1ef5430500")
    static let b1 = header("010000009e555073d0c4f36456db8951f449704d544d2826d9aa60636b40374626780abb8568d2dcae16aefa97bca36d32011c512890edbaaafb26ef46fe981fdc7a32b6c3a7f052f0ff0f1e18a71700")
    static let b2 = header("010000003ac6efa654eaa70cc0ab01d401f70fe7ab516ec1a0de6c1c92fc1c82f142ee390707070707070707070707070707070707070707070707070707070707070707c4a7f052f0ff0f1e834e1700")

    /// The payload of a `headers` message carrying `headers`.
    static func headersPayload(_ headers: [BlockHeader]) -> Data {
        var payload = VarInt(UInt64(headers.count)).serialize()
        for header in headers {
            payload.append(header.serializeCore())
            payload.append(0)
        }
        return payload
    }

    /// The merkle block a node sends for a block whose only transaction is
    /// the one its header commits to.
    /// - Parameter matched: Whether that transaction matched the filter
    static func merkleBlock(for header: BlockHeader, matched: Bool) -> Data {
        MerkleBlockMessage(
            header: header,
            totalTransactions: 1,
            hashes: [header.merkleRoot],
            flags: Data([matched ? 0x01 : 0x00])
        ).serialize()
    }

    private static func hex(_ string: String) -> Data {
        Data(hexString: string) ?? Data()
    }

    private static func header(_ string: String) -> BlockHeader {
        BlockHeader.parse(from: hex(string)) ?? BlockHeader(
            version: 0, prevBlock: Data(count: 32), merkleRoot: Data(count: 32), timestamp: 0, bits: 0, nonce: 0
        )
    }
}
